import java.io.*;
import java.util.*;

public class VariantFive {
    public static void main(String[] args) throws Exception {
        new VariantFive().runProgram();
    }

    public void runProgram() throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);
        String[] tokens = br.readLine().split(" ");
        int n = Integer.parseInt(tokens[0]);
        long k = Long.parseLong(tokens[1]);
        final long MOD = 998244353;

        if (k >= n) {
            pw.println(0);
            pw.close();
            return;
        }

        long[] factorials = new long[n + 1];
        long[] invFactorials = new long[n + 1];
        factorials[0] = 1;
        invFactorials[0] = 1;

        for (int i = 1; i <= n; i++) {
            factorials[i] = (factorials[i - 1] * i) % MOD;
            invFactorials[i] = computeInverse(factorials[i], MOD);
        }

        int r = (int) (n - k);
        long totalSum = 0;

        for (int i = 1; i <= r; i++) {
            long term = factorials[r] * invFactorials[r - i] % MOD;
            term = term * invFactorials[i] % MOD;
            term = term * power(i, n, MOD) % MOD;
            if ((r - i) % 2 == 1) {
                term = -term;
            }
            totalSum = (totalSum + term + MOD) % MOD;
        }

        long finalAnswer;
        if (k == 0) {
            finalAnswer = totalSum * factorials[n] % MOD;
            finalAnswer = finalAnswer * invFactorials[r] % MOD;
            finalAnswer = finalAnswer * invFactorials[n - r] % MOD;
        } else {
            finalAnswer = 2 * totalSum % MOD;
            finalAnswer = finalAnswer * factorials[n] % MOD;
            finalAnswer = finalAnswer * invFactorials[r] % MOD;
            finalAnswer = finalAnswer * invFactorials[n - r] % MOD;
        }
        pw.println(finalAnswer);
        pw.close();
    }

    private long power(long base, int exp, long mod) {
        long res = 1;
        long cur = base % mod;
        for (int i = 0; i < exp; i++) {
            res = (res * cur) % mod;
        }
        return res;
    }

    private long computeInverse(long a, long m) {
        return power(a, (int) m - 2, m);
    }
}
